# Close a period, fixing its due-total as it stands now; an unknown or already closed period is refused (400).
load:
  class: net.officefloor.hq.app.period.LoadPeriod
  govern: [ transaction ]
  next: close
close:
  class: net.officefloor.hq.app.period.ClosePeriod
  govern: [ transaction ]
  next: save
save:
  class: net.officefloor.hq.app.period.SavePeriodClosed
  govern: [ transaction ]
  next: audit
audit:
  class: net.officefloor.hq.app.period.AuditPeriodClosed
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.period.RespondWithPeriod
  govern: [ transaction ]
package net.officefloor.hq.app.period;

import java.math.BigDecimal;
import java.util.List;
import java.util.Map;
import java.util.function.Function;
import java.util.stream.Collectors;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.claim.LateCharge;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.rate.Rate;
import net.officefloor.hq.app.rate.RateRepository;
import net.officefloor.hq.app.setting.SettingRepository;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/**
 * Closes the period, fixing its due-total as it stands now: the dues (figures plus any late charge) of the counting
 * claims dated in it, added up (n/a skipped). Refused (400) when it is already closed.
 */
public class ClosePeriod {
    public void close(@Val Period period, ClaimRepository claims, PersonRepository people, RateRepository rates,
            SettingRepository settings, SheetRepository sheets, Out<Period> closed) throws InvalidPeriodException {
        if (period.closed()) {
            throw new InvalidPeriodException("The period " + period.name() + " is already closed.");
        }
        Map<Long, Person> byId = people.findAll(period.sheetId()).stream()
                .collect(Collectors.toMap(Person::id, Function.identity()));
        List<Rate> sheetRates = rates.findAll(period.sheetId());
        BigDecimal floor = settings.floor(period.sheetId());
        LateCharge late = settings.lateCharge(period.sheetId(), sheets.today(period.sheetId()));
        BigDecimal total = BigDecimal.ZERO.setScale(2);
        for (Claim claim : claims.findAll(period.sheetId())) {
            Person person = byId.get(claim.personId());
            if (person == null || !person.counts(claim) || !period.contains(claim.date())) {
                continue;
            }
            BigDecimal figure = claim.due(Rate.inForce(sheetRates, person.gradeOn(claim.date()), claim.date()), floor, late);
            if (figure != null) {
                total = total.add(figure);
            }
        }
        closed.set(period.close(total));
    }
}
package net.officefloor.hq.app.period;

import net.officefloor.plugin.variable.Val;

public class SavePeriodClosed {
    public void save(@Val Period period, PeriodRepository repository) {
        repository.saveClosed(period);
    }
}
package net.officefloor.hq.app.period;

import net.officefloor.hq.app.Audit;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.RequestParam;

/** Records the period just closed, with the due-total it fixed. */
public class AuditPeriodClosed {
    public void audit(@Val Period period, @RequestParam("user") String user, Audit audit) {
        audit.record("PERIOD_CLOSED sheet=" + period.sheetId() + " by=" + user + " period=" + period.name()
                + " total=" + period.closedTotal().setScale(2).toPlainString());
    }
}
package net.officefloor.hq.app.period;

import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.PathVariable;

/** Loads the sheet's period named in the path; refused (400) when there is none. */
public class LoadPeriod {
    public void load(@PathVariable("sheetId") String sheetId, @PathVariable("name") String name,
            PeriodRepository repository, Out<Period> period) throws InvalidPeriodException {
        Period found = repository.find(sheetId, name);
        if (found == null) {
            throw new InvalidPeriodException("No such period: " + name);
        }
        period.set(found);
    }
}
package net.officefloor.hq.app.period;

import java.sql.ResultSet;
import java.sql.SQLException;
import java.time.LocalDate;
import java.util.List;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Repository;

@Repository
public class PeriodRepository {

    private static final String COLUMNS = "sheet_id, name, from_date, to_date, closed, closed_total";

    private final JdbcTemplate jdbc;

    public PeriodRepository(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    /** The sheet's periods, earliest first. */
    public List<Period> findAll(String sheetId) {
        return jdbc.query("SELECT " + COLUMNS + " FROM period WHERE sheet_id = ? ORDER BY from_date",
                PeriodRepository::map, sheetId);
    }

    /** The sheet's period with this name, or null. */
    public Period find(String sheetId, String name) {
        List<Period> found = jdbc.query("SELECT " + COLUMNS + " FROM period WHERE sheet_id = ? AND name = ?",
                PeriodRepository::map, sheetId, name);
        return found.isEmpty() ? null : found.get(0);
    }

    /** The sheet's closed period containing the date, or null. */
    public Period closedOn(String sheetId, LocalDate date) {
        return findAll(sheetId).stream().filter((p) -> p.closed() && p.contains(date)).findFirst().orElse(null);
    }

    public void insert(Period period) {
        jdbc.update("INSERT INTO period (sheet_id, name, from_date, to_date) VALUES (?, ?, ?, ?)",
                period.sheetId(), period.name(), period.from(), period.to());
    }

    /** Store the period's closed flag and fixed due-total. */
    public void saveClosed(Period period) {
        jdbc.update("UPDATE period SET closed = ?, closed_total = ? WHERE sheet_id = ? AND name = ?",
                period.closed(), period.closedTotal(), period.sheetId(), period.name());
    }

    private static Period map(ResultSet rs, int n) throws SQLException {
        return new Period(rs.getString("sheet_id"), rs.getString("name"), rs.getObject("from_date", LocalDate.class),
                rs.getObject("to_date", LocalDate.class), rs.getBoolean("closed"), rs.getBigDecimal("closed_total"));
    }
}
package net.officefloor.hq.app.period;

import java.math.BigDecimal;
import java.time.LocalDate;

/**
 * A period of a sheet: its name (unique on the sheet) and its from and to dates, both inclusive. A closed
 * period keeps the due-total fixed when it was closed ({@code closedTotal}; null while open).
 */
public record Period(String sheetId, String name, LocalDate from, LocalDate to, boolean closed,
        BigDecimal closedTotal) {

    /** A new, open period. */
    public Period(String sheetId, String name, LocalDate from, LocalDate to) {
        this(sheetId, name, from, to, false, null);
    }

    /** Whether the period shares a day with the other. */
    public boolean overlaps(Period other) {
        return !from.isAfter(other.to()) && !other.from().isAfter(to);
    }

    /** Whether the date falls in the period, both ends included. */
    public boolean contains(LocalDate date) {
        return !date.isBefore(from) && !date.isAfter(to);
    }

    /** The same period, closed with its due-total fixed. */
    public Period close(BigDecimal total) {
        return new Period(sheetId, name, from, to, true, total);
    }
}
package net.officefloor.hq.app.setting;

/** The role a user name has on a sheet. */
public record UserRole(String sheetId, String user, Role role) {
